// ── Pattern 1: Factorial — the canonical recursive function ──────
function factorial(n) {
  // Base case: smallest input we handle directly
  if (n <= 1) return 1;
  // Recursive case: shrink n, trust factorial(n-1) is correct
  return n * factorial(n - 1);
}
console.log(factorial(1)); // 1
console.log(factorial(4)); // 24
console.log(factorial(6)); // 720

// ── Pattern 2: Counting down — simpler to trace manually ─────────
function countDown(n) {
  if (n <= 0) {             // base case
    console.log('Done!');
    return;
  }
  console.log(n);           // work before the recursive call
  countDown(n - 1);         // recursive case — n shrinks
}
countDown(5);
// prints: 5, 4, 3, 2, 1, Done!

// ── Pattern 3: Sum of a list ─────────────────────────────────────
function sumList(arr) {
  if (arr.length === 0) return 0;           // base case: empty list
  return arr[0] + sumList(arr.slice(1));    // first + sum of rest
}
console.log(sumList([1, 2, 3, 4, 5])); // 15

// ── Binary tree node structure ────────────────────────────────────
const tree = {
  value: 4,
  left:  { value: 2, left: { value: 1, left: null, right: null },
                     right: { value: 3, left: null, right: null } },
  right: { value: 6, left: { value: 5, left: null, right: null },
                     right: { value: 7, left: null, right: null } }
};

// ── Pre-order: node → left → right ───────────────────────────────
function preOrder(node) {
  if (!node) return;             // base case: null node
  console.log(node.value);       // visit node FIRST
  preOrder(node.left);
  preOrder(node.right);
}

// ── In-order: left → node → right ────────────────────────────────
function inOrder(node) {
  if (!node) return;
  inOrder(node.left);
  console.log(node.value);       // visit node BETWEEN children
  inOrder(node.right);
}

// ── Post-order: left → right → node ──────────────────────────────
function postOrder(node) {
  if (!node) return;
  postOrder(node.left);
  postOrder(node.right);
  console.log(node.value);       // visit node LAST
}

// ── Sum all nodes — post-order accumulation ───────────────────────
function sumTree(node) {
  if (!node) return 0;           // null subtree contributes 0
  const left  = sumTree(node.left);
  const right = sumTree(node.right);
  return node.value + left + right; // combine sub-results
}

console.log('In-order:');
inOrder(tree);  // 1 2 3 4 5 6 7
console.log('Sum:', sumTree(tree)); // Sum: 28

// ── Naive Fibonacci — correct but exponential: Θ(φⁿ) ≈ Θ(1.618ⁿ) ──
function fibNaive(n) {
  if (n <= 1) return n;            // base cases: fib(0)=0, fib(1)=1
  return fibNaive(n - 1) + fibNaive(n - 2);
}
console.log(fibNaive(10));  // 55   — fast enough
console.log(fibNaive(35));  // 9227465 — noticeably slow already
// fibNaive(50) makes ~4 × 10¹⁰ calls — minutes of CPU time

// ── Memoized Fibonacci — O(n) time, O(n) space ────────────────────
function fibMemo(n, memo = new Map()) {
  if (memo.has(n)) return memo.get(n);  // return cached result
  if (n <= 1) return n;                 // base cases
  const result = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
  memo.set(n, result);                  // cache before returning
  return result;
}
console.log(fibMemo(10));   // 55    — instant
console.log(fibMemo(50));   // 12586269025  — instant
console.log(fibMemo(100));  // 354224848179262000000 — instant, but NOT exact:
// fib(79) and above exceed Number.MAX_SAFE_INTEGER (2^53 − 1), so doubles round.
// Recursion depth is still n: fibMemo(20000) overflows the stack.

// ── Bottom-up DP — O(n) time, O(1) space ─────────────────────────
// Avoids recursion entirely; builds the table from small to large
function fibDP(n) {
  if (n <= 1) return n;
  let prev = 0, curr = 1;
  for (let i = 2; i <= n; i++) {
    [prev, curr] = [curr, prev + curr];  // slide the window
  }
  return curr;
}
console.log(fibDP(50));  // 12586269025 — no stack growth at all

// Exact big values: same loop with BigInt
function fibBig(n) {
  let prev = 0n, curr = 1n;
  for (let i = 0; i < n; i++) [prev, curr] = [curr, prev + curr];
  return prev;
}
console.log(fibBig(100)); // 354224848179261915075n — exact

// ── Same tree walk, two ways ─────────────────────────────────────
const tree = {
  value: 4,
  left:  { value: 2, left: { value: 1, left: null, right: null },
                     right: { value: 3, left: null, right: null } },
  right: { value: 6, left: { value: 5, left: null, right: null },
                     right: { value: 7, left: null, right: null } }
};

// Recursive pre-order: the CALL STACK remembers where to go next
function preOrderRecursive(node, out = []) {
  if (!node) return out;
  out.push(node.value);
  preOrderRecursive(node.left, out);
  preOrderRecursive(node.right, out);
  return out;
}

// Iterative pre-order: an explicit ARRAY stack (on the heap) does the same job
function preOrderIterative(root) {
  const out = [];
  const stack = root ? [root] : [];
  while (stack.length > 0) {
    const node = stack.pop();
    out.push(node.value);
    if (node.right) stack.push(node.right); // push right first...
    if (node.left)  stack.push(node.left);  // ...so left is popped first
  }
  return out;
}

console.log(preOrderRecursive(tree).join(' ')); // 4 2 1 3 6 5 7
console.log(preOrderIterative(tree).join(' ')); // 4 2 1 3 6 5 7

// A degenerate "tree" that is really a 100,000-node linked list
let deep = null;
for (let i = 0; i < 100_000; i++) deep = { value: i, left: deep, right: null };

try { preOrderRecursive(deep); } catch (e) { console.log(e.message); } // Maximum call stack size exceeded
console.log(preOrderIterative(deep).length);                           // 100000 — heap stack grows freely
